update.foreach:
UPDATE ${schema}direcciones
SET  drcc_dsc        = #{direccion.descripcion}      , drcc_calle          = #{direccion.calle}         ,
     drcc_numeracion = #{direccion.numeracion}       , drcc_referencia     = #{direccion.referencia}    ,
     cmna_id         = #{direccion.comuna.id}        , sctr_id             = #{direccion.sector.id}     ,
     tpdr_id         = #{direccion.tipoDireccion.id} , drcc_imagen_perfil  = #{direccion.imagenPerfil}  ,
     drcc_latitud    = #{direccion.latitud}          , drcc_longitud       = #{direccion.longitud}      ,
     estd_id         = #{direccion.estado.id}        , drcc_flag_evidencia = #{direccion.flagEvidencia} ,
